// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient, uint256 seed) public {
        vm.assume(recipient != address(this) && recipient != address(0) && recipient != address(c));
        ZeroValueReverter reverter = new ZeroValueReverter();
        address payable reverterAddr = payable(address(reverter));
        vm.deal(address(c), 1000 ether);
        uint256 balBefore = reverterAddr.balance;
        bool ok = true;
        try c.getFirstWithdrawalBonus(reverterAddr) { ok = true; } catch { ok = false; }
        if (!ok) {
            assertTrue(false);
        } else {
            uint256 balAfter = reverterAddr.balance;
            assertTrue(balAfter == balBefore + 100);
        }
    }
}

contract ZeroValueReverter {
    receive() external payable {
        require(msg.value > 0, "no zero-value calls");
    }
}
